def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Complete gaps inside horizontal bars when the two ends match.
    bar_rows = []
    for r, row in enumerate(grid):
        if sum(v != 0 for v in row) >= 3:
            bar_rows.append(r)
            positions = [c for c, value in enumerate(row) if value != 0]
            for a, b in zip(positions, positions[1:]):
                if b > a + 1 and row[a] == row[b]:
                    for c in range(a + 1, b):
                        out[r][c] = row[a]

    # Bottom-anchored vertical strokes pass through the horizontal bars.
    for c in range(w):
        if grid[h - 1][c] == 0:
            continue

        r = h - 1
        while r >= 0 and grid[r][c] != 0:
            r -= 1
        anchor_color = grid[h - 1][c]

        markers = []
        for br in bar_rows:
            color = out[br][c]
            if color != 0:
                markers.append((br, color))

        if not markers:
            continue

        markers.sort()
        first_r, first_color = markers[0]
        for rr in range(first_r + 1):
            out[rr][c] = first_color

        for i in range(1, len(markers)):
            rr, color = markers[i]
            previous_r = markers[i - 1][0]
            for y in range(previous_r + 1, rr + 1):
                out[y][c] = color

        last_r = markers[-1][0]
        for rr in range(last_r + 1, h):
            out[rr][c] = anchor_color

    return out
